mapper.select:
SELECT  FROM crm_appointment WHERE tenant_id=#{tenantId}

AND customer_id=#{customerId}
AND institution_id=#{institutionId}
AND status=#{status}
ORDER BY id DESC LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*) FROM crm_appointment WHERE tenant_id=#{tenantId}

AND customer_id=#{customerId}
AND institution_id=#{institutionId}
AND status=#{status}

SELECT DISTINCT crm_redemption.id,crm_redemption.appointment_id AS appointmentId,
  crm_redemption.customer_id AS customerId,crm_redemption.institution_id AS institutionId,
  crm_redemption.owner_staff_id AS ownerStaffId,crm_redemption.team_id AS teamId,
  crm_redemption.service_at AS serviceAt,crm_redemption.evidence_ref AS evidenceRef,
  crm_redemption.voucher_file_id AS voucherFileId,crm_redemption.status,
  crm_redemption.settlement_status AS settlementStatus,crm_redemption.idempotency_key AS idempotencyKey,
  crm_redemption.posted_by AS postedBy,crm_redemption.posted_at AS postedAt,
  crm_redemption.created_at AS createdAt,crm_redemption.version
FROM crm_redemption

  INNER JOIN crm_redemption_line l ON l.tenant_id=crm_redemption.tenant_id
    AND l.redemption_id=crm_redemption.id AND l.project_id=#{projectId}

WHERE crm_redemption.tenant_id=#{tenantId}

AND crm_redemption.customer_id=#{customerId}
AND crm_redemption.institution_id=#{institutionId}
AND crm_redemption.status=#{status}
ORDER BY crm_redemption.id DESC LIMIT #{size} OFFSET #{offset}

SELECT COUNT(DISTINCT crm_redemption.id) FROM crm_redemption

  INNER JOIN crm_redemption_line l ON l.tenant_id=crm_redemption.tenant_id
    AND l.redemption_id=crm_redemption.id AND l.project_id=#{projectId}

WHERE crm_redemption.tenant_id=#{tenantId}

AND crm_redemption.customer_id=#{customerId}
AND crm_redemption.institution_id=#{institutionId}
AND crm_redemption.status=#{status}

SELECT  FROM crm_redemption_reversal WHERE tenant_id=#{tenantId}

AND customer_id=#{customerId}
AND institution_id=#{institutionId}
AND status=#{status}
ORDER BY id DESC LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*) FROM crm_redemption_reversal WHERE tenant_id=#{tenantId}

AND customer_id=#{customerId}
AND institution_id=#{institutionId}
AND status=#{status}
